Here is the commit message:
crypto: octeontx2 - fix signedness bug in
 cptvf_register_interrupts()

The "num_vec" has to be signed for the error handling to work.

Fixes: 19d8e8c7be15 ("crypto: octeontx2 - add virtual function driver support")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>

Here is the root cause:
The bug was caused by using an unsigned integer type (`u32`) for the variable `num_vec`, which is assigned the result of `pci_msix_vec_count(cptvf->pdev)`. If this function returns a negative value (indicating an error), the comparison `num_vec <= 0` would not work as intended, leading to incorrect error handling. Changing `num_vec` to a signed integer type (`int`) allows for proper handling of negative values, ensuring that error conditions are correctly identified.

Here is the patch:

 static int cptvf_register_interrupts(struct otx2_cptvf_dev *cptvf)
 {
 	int ret, irq;
-	u32 num_vec;
+	int num_vec;

 	num_vec = pci_msix_vec_count(cptvf->pdev);
 	if (num_vec <= 0)
 		return -EINVAL;

 	/* Enable MSI-X */
 	ret = pci_alloc_irq_vectors(cptvf->pdev, num_vec, num_vec,
 				    PCI_IRQ_MSIX);
 	if (ret < 0) {
 		dev_err(&cptvf->pdev->dev,
 			"Request for %d msix vectors failed\n", num_vec);
 		return ret;
 	}
 	irq = pci_irq_vector(cptvf->pdev, OTX2_CPT_VF_INT_VEC_E_MBOX);
 	/* Register VF<=>PF mailbox interrupt handler */
 	ret = devm_request_irq(&cptvf->pdev->dev, irq,
 			       otx2_cptvf_pfvf_mbox_intr, 0,
 			       "CPTPFVF Mbox", cptvf);
 	if (ret)
 		return ret;
 	/* Enable PF-VF mailbox interrupts */
 	cptvf_enable_pfvf_mbox_intrs(cptvf);

 	ret = otx2_cpt_send_ready_msg(&cptvf->pfvf_mbox, cptvf->pdev);
 	if (ret) {
 		dev_warn(&cptvf->pdev->dev,
 			 "PF not responding to mailbox, deferring probe\n");
 		cptvf_disable_pfvf_mbox_intrs(cptvf);
 		return -EPROBE_DEFER;
 	}
 	return 0;
 }



